class Solution { fun amountOfTime(root:TreeNode?,start:Int):Int{val graph=HashMap<Int,MutableList<Int>>();fun build(node:TreeNode?){if(node==null)return;graph.getOrPut(node.`val`){mutableListOf()};for(child in listOf(node.left,node.right))if(child!=null){graph[node.`val`]!!.add(child.`val`);graph.getOrPut(child.`val`){mutableListOf()}.add(node.`val`);build(child)}};build(root);val queue=java.util.ArrayDeque<Int>();val seen=HashSet<Int>();queue.add(start);seen.add(start);var minutes=-1;while(queue.isNotEmpty()){minutes++;repeat(queue.size){val node=queue.removeFirst();for(next in graph[node]!!)if(seen.add(next))queue.add(next)}};return minutes} }
